const POP_COLORS=WALLET_COLORS,POP_PATTERNS=WALLET_PATTERNS,POP_DEFAULT={...WALLET_DEFAULT};
let popDraft={...POP_DEFAULT},popSourcePromise,popFrame;
function restorePopDraft(raw){const old=walletDraft;restoreWalletDraft(raw);popDraft={...walletDraft};walletDraft=old;if(document.querySelector('#pop-form'))setupPopEditor();}
const POP_BASE_IMAGE='data:image/webp;base64,';
function popPersonalization(){
 return `<section class="page-heading"><h1>Personalización</h1><p>Tu color. Tu patrón. Tu Power Case.</p></section>${personalizationTabs('pops')}<section class="pop-editor" id="pop-editor"><div class="pop-preview"><span class="eyebrow">VISTA PREVIA DE TU DISEÑO</span><canvas id="pop-canvas" width="720" height="720" role="img" aria-label="Vista previa de tu PopSocket personalizado"></canvas><p class="note">Prueba de diseño sobre el PopSocket Power Case.</p><p id="pop-render-status" role="status" aria-live="polite"></p></div><form id="pop-form"><span class="eyebrow">POPSOCKET</span><h2>Crea tu combinación.</h2><p class="accessory-detail-price">$90.00 MXN</p><p>Combina el color del PopSocket con un patrón. La firma Power Case se conserva en tu diseño.</p><fieldset><legend>Color del PopSocket</legend><div class="pop-palette">${POP_COLORS.map(([name,color])=>`<button type="button" data-pop-color="${color}" title="${name}" aria-label="Color ${name}" aria-pressed="${popDraft.background.toLowerCase()===color}" style="--pop-color:${color}"><span aria-hidden="true"></span></button>`).join('')}</div><label class="pop-color-field">Elige otro color<input type="color" name="background" value="${popDraft.background}"></label></fieldset><fieldset><legend>Patrón</legend><div class="pop-patterns">${Object.entries(POP_PATTERNS).map(([id,name])=>`<button type="button" data-pop-pattern="${id}" aria-pressed="${popDraft.pattern===id}"><span class="pop-pattern-icon pop-pattern-${id}" aria-hidden="true"></span>${name}</button>`).join('')}</div></fieldset><label class="pop-color-field">Color del patrón<input type="color" name="accent" value="${popDraft.accent}"></label><fieldset class="pop-brand-controls"><legend>Firma POWER CASE</legend><label class="pop-color-field">Color de la firma<input type="color" name="brandColor" value="${popDraft.brandColor}"></label><label class="pop-brand-auto"><input type="checkbox" name="brandAuto" ${popDraft.brandAuto?'checked':''}> Ajustar contraste automáticamente</label></fieldset><div class="pop-editor-actions"><button type="button" class="button dark" data-pop-download>Guardar diseño</button><button type="button" class="text-link" data-pop-reset>Restablecer</button></div><p class="note">Guarda el diseño en favoritos para añadirlo a la bolsa cuando quieras.</p></form></section>`;
}
async function popSource(){
 popSourcePromise??=new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>{const canvas=document.createElement('canvas');canvas.width=canvas.height=720;const context=canvas.getContext('2d',{willReadFrequently:true});context.drawImage(image,0,0,720,720);resolve(context.getImageData(0,0,720,720));};image.onerror=()=>reject(Error('No se pudo cargar la PopSocket.'));image.src=POP_BASE_IMAGE;}).catch(error=>{popSourcePromise=null;throw error;});
 return popSourcePromise;
}
async function drawPop(canvas=document.querySelector('#pop-canvas'),savedDraft=null){
 if(!canvas)return;
 try{
 const source=await popSource();if(!canvas.isConnected)return;const draft={...(savedDraft||popDraft)},size=720;
 const layer=document.createElement('canvas');layer.width=layer.height=size;const ctx=layer.getContext('2d');walletPattern(ctx,draft.background,draft.accent,draft.pattern,size);const pattern=ctx.getImageData(0,0,size,size).data;
 const result=new ImageData(new Uint8ClampedArray(source.data),size,size),cos=Math.cos(.23),sin=Math.sin(.23);
 for(let y=80;y<600;y++)for(let x=75;x<500;x++){
 const dx=x-287,dy=y-344,u=cos*dx+sin*dy,v=-sin*dx+cos*dy,r=(u/191)**2+(v/248)**2;if(r>.94)continue;
 const i=(y*size+x)*4;let j=i;
 if(x>220&&x<335&&y>250&&y<390)j=(y*size+150+(x%40))*4;
 if(x>150&&x<360&&y>475&&y<550)j=((y-65)*size+x)*4;
 const light=.2126*source.data[j]+.7152*source.data[j+1]+.0722*source.data[j+2],shade=.48+light/255*.7,alpha=Math.min(1,(.94-r)*70);
 for(let c=0;c<3;c++)result.data[i+c]=source.data[i+c]*(1-alpha)+Math.min(255,pattern[i+c]*shade)*alpha;
 }
 const context=canvas.getContext('2d');context.putImageData(result,0,0);
 const color=draft.brandAuto?((parseInt(draft.background.slice(1,3),16)*.2126+parseInt(draft.background.slice(3,5),16)*.7152+parseInt(draft.background.slice(5,7),16)*.0722)>145?'#161616':'#faf7f0'):draft.brandColor;
 context.save();context.translate(287,344);context.rotate(.23);context.scale(.77,1);context.fillStyle=color;context.font='500 17px Arial';context.textAlign='center';context.fillText('POWER CASE',0,158);context.restore();canvas.dataset.brandColor=color;
 canvas.setAttribute('aria-label','PopSocket personalizado: '+POP_PATTERNS[draft.pattern]);if(!savedDraft){document.querySelector('#pop-render-status').textContent='';if(draft.brandAuto)document.querySelector('#pop-form').elements.brandColor.value=color;}
 }catch{if(!savedDraft&&canvas.isConnected)document.querySelector('#pop-render-status').textContent='No se pudo generar la vista previa. Intenta de nuevo.';}
}
function setupPopEditor(){
 const form=document.querySelector('#pop-form');if(!form)return;
 form.elements.background.value=popDraft.background;form.elements.accent.value=popDraft.accent;form.elements.brandColor.value=popDraft.brandColor;form.elements.brandAuto.checked=popDraft.brandAuto;form.elements.accent.disabled=popDraft.pattern==='plain';
 for(const button of form.querySelectorAll('[data-pop-color]'))button.setAttribute('aria-pressed',button.dataset.popColor===popDraft.background.toLowerCase());
 for(const button of form.querySelectorAll('[data-pop-pattern]'))button.setAttribute('aria-pressed',button.dataset.popPattern===popDraft.pattern);
 form.style.setProperty('--pop-background',popDraft.background);form.style.setProperty('--pop-accent',popDraft.accent);
 cancelAnimationFrame(popFrame);popFrame=requestAnimationFrame(()=>drawPop());
}
document.addEventListener('input',event=>{
 if(!event.target.closest('#pop-form')||!['background','accent','brandColor','brandAuto'].includes(event.target.name))return;
 popDraft={...popDraft,[event.target.name]:event.target.type==='checkbox'?event.target.checked:event.target.value,...(event.target.name==='brandColor'?{brandAuto:false}:{})};setupPopEditor();workspace?.changed();
});
document.addEventListener('click',async event=>{
 const palette=event.target.closest('[data-pop-color]'),pattern=event.target.closest('[data-pop-pattern]'),reset=event.target.closest('[data-pop-reset]');
 if(palette||pattern||reset){popDraft=reset?{...POP_DEFAULT}:{...popDraft,...(palette?{background:palette.dataset.popColor}:{pattern:pattern.dataset.popPattern})};setupPopEditor();workspace?.changed();}
 const download=event.target.closest('[data-pop-download]');if(!download)return;
 if(!session&&accountInitializing)await accountInitialization;
 if(!session){account();return;}
 if(!workspace?.ready){toast('Espera a que termine de cargar tu cuenta.');return;}
 download.disabled=true;
 try{
  const draft={...popDraft};
  if(!savedWallets.some(item=>item.kind==='pop'&&JSON.stringify(item.draft)===JSON.stringify(draft)))savedWallets.push({id:'wallet-'+crypto.randomUUID(),kind:'pop',draft});
  workspace.changed();refreshFavorites();toast('Diseño añadido a tus favoritos.');
 }catch{toast('No se pudo guardar el diseño. Inténtalo de nuevo.');}finally{download.disabled=false;}

});

